const out={};
out.passage = window.SugarCube.State.passage;
out.quests_engine_meta = 'n/a';
out.cardCount = (window.SugarCube.setup.quests_cards||[]).length;
const hd = window.SugarCube.setup.help_data||{};
out.helpNpcKeys = Object.keys(hd.npcs||{});
// slug resolution per npc + pickQuestsCard result
out.perNpc = [];
for(const uuid of Object.keys(hd.npcs||{})){
  let slug=null, card=null;
  try{ slug = window.SugarCube.setup.npcSlugForId(uuid); }catch(e){ slug='ERR:'+e.message; }
  try{ const c = window.SugarCube.setup.pickQuestsCard(slug); card = c? (c.text||'').slice(0,30) : null; }catch(e){ card='ERR:'+e.message; }
  out.perNpc.push({uuid:uuid.slice(0,8), slug, card});
}
// story goals
try{ out.storyGoals = (window.SugarCube.setup.pickQuestsCards('story_goals')||[]).length; }catch(e){ out.storyGoals='ERR:'+e.message; }
// sample card npc_id values
out.sampleCardNpcIds = [...new Set((window.SugarCube.setup.quests_cards||[]).map(c=>c.npc_id))];
return JSON.stringify(out,null,1);
